WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (586, 'J2', $t$ASK 586 J2: the [L2] entry of a judge's break quotes the gloss a side gave, with its round; a record-only check (E-L2G) sends a faulty entry back once$t$,
  $t$When a judge's break turns on a word's meaning, the [L2] entry quotes the gloss as a side gave it in the rounds, word for word, with the round; a judge's LINK BROKEN or FORCED line whose numbered [L2] entry does not do so goes back once; the judge keeps the decision (ruling 428); the gloss is a side's own and not the record's lexicon row (rulings 382 and 383). (Plan ask586/w3/plan586.md rev 6, J2; texts ask586/w3/texts586_J2J3J6.md section 1; W4's notes_j2.md; the operator's press "Write J2, not counted".)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write J2, not counted" at 08:11 CST 2026-11-24, with no run live (Wall 11523; audit 41394). Engine moMxiV4Irg1uRBZN 1afd3099 to 489b977b; child MqQHRl7mQQ0z8QdT 18570075 to e086bb3a. Target B (on the ASK 595 follow-on base), LIB b243080d9bd0b10c. OPTION A is live: an uncured E-L2G item is recorded and counts against no seat. Option B (counted) is not built. What changed: (1) Panel Build and Build Independent Verdict: both [L2] forms, the FORCED form and the collision line form, read [L2] <word> (<Strong's number>): "<the gloss as a side quoted it, word for word>" [<round>], and after each stands "If the deciding step of a break says more than the quoted gloss says, say so in DECIDES and name the verse that carries it." Build Independent Verdict does not run; it changes only so the twins stay equal. (2) Shared Library, engine and child: line 2953 (the send-back form of a break) gives the same entry; line 3564 gains the check (rule E-L2G; faults 1, 2 and 3; the judge's whole line stored); lines 2784, 2789, 2929 and 2959 carry the record (never counted as silence; the row reads "[L2] GLOSS NOT QUOTED (E-L2G, ASK 586 J2, fault n): record-only, counts against no seat; the judge keeps the decision (ruling 428)"). No setting changes. DEVIATION from W3's texts 1.2, accepted by W1 (Wall 11512): the counting clause of line 2953 is not extended with "and the quoted gloss stands in the round named, beside that number", because under option A the E-COL [L2] count does not read the gloss and the clause would tell the judge a rule the engine does not apply. The E-COL count reads the new form as the old (test E1), so no count changes. Measured on stored rows 1263 to 1274 (4 runs; out_c2m.txt): 38 of 67 break lines hold a numbered [L2] entry, all in the old form, so each would go back once (run 42071: 11 of 13); none counts under option A. The new judges' text asks for the form, so a live run should send back fewer; not measured. LIMITS, stated and not changed: the send-back builders return before line 3564 on a pass where no enforcer item exists (14 of 123 panel passes and 22 of 72 alternate passes in 30 days, as notes_j2.md gives it), so the item goes out only on a pass that holds an enforcer item; K-GLS (TRIAL, record-only) reads only the old form and reads nothing from the new; whether a deciding step says more than the gloss is not checked by code; a block that holds several numbers lets a gloss given for another number pass as beside. The path: texts draft 2 (W1 PASS); build rev 0, four targets (Wall 11511); W1 PASS, deviation accepted (Wall 11512); the press; the write (Wall 11523); W1 readback MATCH (Wall 11527). IN PART, because no run has executed on 489b977b (debate_results last row 21:57 CST 2026-11-23, run 42071): the form, the check and the record are shown by t_j2, by the end-to-end run on row 1272 and by the readback, not by a run. After this write the ASK 586 J3 build was re-cut on this base (Wall 11525, W1 PASS 11528); not written at the draft of this row.$t$,
  '11381, 11511, 11512, 11523, 11527',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$His press at 08:11 CST 2026-11-24 in W4's thread: "Write J2, not counted" (as Wall 11523 and audit 41394 give it). The press chooses option A. W3 did not see the card or the press.$t$::text),
  $j${"answer": "Write J2, not counted", "source": "Wall 11523; audit 41394 (card cmsg_017ZQamDMHrS6fqMHnQDVo58FbtqxmgbynjNxaCvSdp1Fs)", "thread": "W4", "press_time": "08:11 CST 2026-11-24", "question": "not in the record W3 read (the card is in W4's thread); the card text is ask586/w4/j2/card586j2.md 064c1427"}$j$::jsonb,
  'W4',
  $j${"md5": "7b81e80d", "path": "ask586/w3/plan586.md", "commit": "not read by W3 for this row", "note": "W3's plan rev 6, J2 (W1 PASS with C6 and C7, Wall 11381); the texts are ask586/w3/texts586_J2J3J6.md 78ba341a section 1", "source": "md5sum by W3; Wall 11511, 11512"}$j$::jsonb,
  $j$[{"md5": "73f58cb0", "path": "ask586/w4/j2/target_engine_j2_on595c.json", "note": "the engine target B, on the ASK 595 follow-on base 1afd3099; graded, written and read back", "source": "md5sum by W3; Wall 11512, 11527"}, {"md5": "1ee36e0b", "path": "ask586/w4/j2/target_child_j2_on595c.json", "note": "the child target B, on 18570075", "source": "md5sum by W3; Wall 11512, 11527"}, {"md5": "823dfc37", "path": "ask586/w4/j2/notes_j2.md", "note": "build notes rev 0", "source": "md5sum by W3"}, {"md5": "b885f7da", "path": "ask586/w4/j2/build_j2.cjs", "note": "the build script", "source": "md5sum by W3"}, {"md5": "6ab2bba5", "path": "ask586/w4/j2/t_j2.cjs", "note": "the test, 37 cases", "source": "md5sum by W3"}, {"md5": "5cfd9558", "path": "ask586/w4/j2/out_t_j2_on595c.txt", "note": "test output on target B; the same md5 as write/t_j2_at_write.txt", "source": "md5sum by W3"}, {"md5": "efa0f54d", "path": "ask586/w4/j2/write/standing_at_write.txt", "note": "the standing set at the write", "source": "md5sum by W3"}, {"md5": "1e60dc7c", "path": "ask586/w4/j2/c2m.cjs", "note": "the measure on stored rows 1263 to 1274", "source": "md5sum by W3"}, {"md5": "4a7d4d20", "path": "ask586/w4/j2/out_c2m.txt", "note": "its output", "source": "md5sum by W3"}, {"md5": "4bbaf86d", "path": "ask586/w4/j2/sbrun_j2.cjs", "note": "the end-to-end run of the built send-back builders on row 1272", "source": "md5sum by W3"}, {"md5": "064c1427", "path": "ask586/w4/j2/card586j2.md", "note": "the card text", "source": "md5sum by W3"}, {"md5": "84c5f0ba", "path": "ask586/w4/j2/write/fetchback_eng586j2.json", "note": "fetch-back after the write", "source": "md5sum by W3"}, {"md5": "bc147e90", "path": "ask586/w4/j2/write/fetchback_child586j2.json", "note": "fetch-back after the write, child", "source": "md5sum by W3"}, {"md5": "82616094", "path": "ask586/w4/j2/write/write586j2.sh", "note": "the write script; it takes base A, B, C or D and refuses any other, and refuses while a run is live", "source": "md5sum by W3"}, {"md5": "78ba341a", "path": "ask586/w3/texts586_J2J3J6.md", "note": "W3's instruction texts, section 1 (J2)", "source": "md5sum by W3; Wall 11511, 11512"}]$j$::jsonb,
  $j${"copy": "restore the engine and the child together from ask586/w4/j2/write/revert_eng586j2.json 52757d6b and revert_child586j2.json 4659567a (to 1afd3099 and 18570075).", "path": "ask586/w4/j2/write/revert_eng586j2.json; ask586/w4/j2/write/revert_child586j2.json", "source": "audit 41394; Wall 11523; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS, deviation accepted (build rev 0, targets A to D: only Panel Build, Build Independent Verdict and the Shared Library change; a hunk walk shows texts 1.1 exactly; line 3564 a pure append; texts 1.3 word for word with the option A cost; t_j2 37 PASS and the standing set 29 PASS rerun by W1 on all four)", "wall_id": 11512, "md5_graded": "73f58cb0", "verdict_norm": "PASS", "source": "Wall 11512; Wall 11527 (\"target B, which I graded at 11512\"); the md5 is md5sum by W3 on ask586/w4/j2/target_engine_j2_on595c.json; W1's posts do not print it"}, {"seat": "W1", "verdict": "PASS (the child target B, the same grade: Shared Library only)", "wall_id": 11512, "md5_graded": "1ee36e0b", "verdict_norm": "PASS", "source": "Wall 11512, 11527; md5sum by W3 on ask586/w4/j2/target_child_j2_on595c.json"}]$j$::jsonb,
  ARRAY['73f58cb0','1ee36e0b'], '[41394]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "1afd3099, 422 nodes", "after": "489b977b, 422 nodes"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "before": "18570075, 156 nodes", "after": "e086bb3a, 156 nodes"}, {"kind": "node text", "name": "Panel Build; Build Independent Verdict", "before": "[L2] <word> (<Strong's number>, <gloss>) in the FORCED form and the collision line form", "after": "[L2] <word> (<Strong's number>): \"<the gloss as a side quoted it, word for word>\" [<round>] in both forms, and one added sentence after each"}, {"kind": "library lines", "name": "Shared Library lines 2953, 3564, 2784, 2789, 2929, 2959, engine and child", "before": "no E-L2G check; line 2953 in the old form", "after": "line 2953 in the new form; the E-L2G check appended to line 3564; the record inserts"}, {"kind": "library", "name": "Shared Library, engine and child", "before": "LIB 04ac120b9bf3a19c", "after": "LIB b243080d9bd0b10c"}]$j$::jsonb,
  $j$[{"name": "t_j2.cjs, 37 cases", "result": "37 PASS on each of targets A to D at the build, at W1's rerun, and on target B at the write: structure; E-COL reads the new form as the old; the check on known-bad row 1272 (fault 1), controls, fault 2 in three cases, fault 3; a line over 1,500 characters stored whole; the record KEEP CURED, CHANGE CURED, silent and error, none counted in any of the 11 count lists", "source": "Wall 11511 item 6; 11512; 11523; notes_j2.md section 2"}, {"name": "sbrun_j2.cjs, end to end on row 1272", "result": "the built Send Back Build and Alt Send Back Build give three E-L2G items that reach the judge's message whole (909, 1,079 and 1,669 characters)", "source": "Wall 11511 item 6; notes_j2.md section 2"}, {"name": "Standing set (ASK 596 core)", "result": "29 PASS, 0 FAIL on the target before the PUT and on live at the readback; the baseline adds the place __ll", "source": "Wall 11511; 11512; 11523; 11527"}, {"name": "Library Check pair", "result": "PASSES: LIB b243080d9bd0b10c", "source": "Wall 11523; 11527"}, {"name": "c2m.cjs on stored rows 1263 to 1274", "result": "38 of 67 break lines hold a numbered [L2] entry in the old form and would go back once; run 42071 11 of 13", "source": "Wall 11511 item 7; out_c2m.txt"}]$j$::jsonb,
  $j$[{"seat": "W1", "wall_id": 11527, "result": "MATCH (own fetch: engine 489b977b, child e086bb3a, both current; live against target B 422 of 422 and 156 of 156 nodes, 0 differences; from the base only Panel Build, Build Independent Verdict and the Shared Library, child the Shared Library; Library Check PASS; standing set 29 PASS)"}]$j$::jsonb,
  $j${"case": "UNEXERCISED. No run has executed on 489b977b (debate_results last row 21:57 CST 2026-11-23). EXPECT on the first run: a judge's break that turns on a word's meaning carries the [L2] entry in the new form; an entry at fault makes one debate_enforcer_log row of rule E-L2G whose flagged_line is the judge's whole line and whose cure_reason holds \"record-only, counts against no seat\"; no seat count moves by it.", "source": "Wall 11523, 11527; SQL by W3; the EXPECT is W3's reading"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet at the draft of this row: version 295 (2e84d933). W3's entry is manual1123/w3/a586j2/em_pairs_586j2_draft1.json 4315f93e (part 08.0, one pair), not graded and not carded at the draft of this row"}$j$::jsonb,
